CREATE TYPE public.hunter_crm_role AS ENUM ('operator');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.hunter_crm_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own operator role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_hunter_operator() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operator'); $$;
REVOKE ALL ON FUNCTION public.is_hunter_operator() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_hunter_operator() TO authenticated;
CREATE FUNCTION public.enroll_hunter_operator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'bossensino@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'operator') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.enroll_hunter_operator() FROM PUBLIC;
CREATE TRIGGER hunter_operator_enrollment AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.enroll_hunter_operator();
INSERT INTO public.user_roles(user_id,role) SELECT id,'operator'::public.hunter_crm_role FROM auth.users WHERE lower(email) = 'bossensino@gmail.com' AND email_confirmed_at IS NOT NULL ON CONFLICT DO NOTHING;
GRANT SELECT ON public.hunter_leads TO authenticated;
CREATE POLICY "Operators read leads" ON public.hunter_leads FOR SELECT TO authenticated USING (public.is_hunter_operator());
CREATE TABLE public.hunter_crm_state (lead_id uuid PRIMARY KEY REFERENCES public.hunter_leads(id) ON DELETE CASCADE, stage text NOT NULL DEFAULT 'new', notes text NOT NULL DEFAULT '', follow_up date, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT hunter_crm_stage CHECK(stage IN ('new','contact','demo','negotiation','won','lost')), CONSTRAINT hunter_crm_notes_length CHECK(length(notes) <= 10000));
GRANT SELECT, INSERT, UPDATE ON public.hunter_crm_state TO authenticated;
GRANT ALL ON public.hunter_crm_state TO service_role;
ALTER TABLE public.hunter_crm_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Operators read followup" ON public.hunter_crm_state FOR SELECT TO authenticated USING(public.is_hunter_operator());
CREATE POLICY "Operators create followup" ON public.hunter_crm_state FOR INSERT TO authenticated WITH CHECK(public.is_hunter_operator());
CREATE POLICY "Operators update followup" ON public.hunter_crm_state FOR UPDATE TO authenticated USING(public.is_hunter_operator()) WITH CHECK(public.is_hunter_operator());
CREATE FUNCTION public.stamp_hunter_crm_update() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TRIGGER hunter_crm_updated BEFORE UPDATE ON public.hunter_crm_state FOR EACH ROW EXECUTE FUNCTION public.stamp_hunter_crm_update();
ALTER PUBLICATION supabase_realtime ADD TABLE public.hunter_leads, public.hunter_crm_state;